package org.dromara.ai.workspace;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.util.*;
@Service
@RequiredArgsConstructor
public class WorkspaceKnowledgeAccess {
 private final JdbcTemplate jdbc;private final AiResourceGuard guard;private final WorkspaceFileStore files;
 public Map<String,Object> base(UUID id,long user,AiResourceGuard.Action action){var r=guard.require(id,user,action);if(!"KNOWLEDGE".equals(r.get("resource_type")))throw new WorkspaceDenied(400,"KnowledgeBaseRequired");return r;}
 public boolean publicOnly(UUID id,long user,AiResourceGuard.Action action){var r=base(id,user,action);return !guard.owner(r,user)&&!guard.acl(id,user,action)&&!guard.acl(id,user,AiResourceGuard.Action.EDIT);}
 public Map<String,Object> document(UUID id,long user,AiResourceGuard.Action action){var rows=jdbc.queryForList("SELECT * FROM ai_knowledge_document WHERE id=? AND deleted_at IS NULL",id);if(rows.size()!=1)throw new WorkspaceDenied(404,"DocumentNotFound");base((UUID)rows.getFirst().get("base_id"),user,action);return rows.getFirst();}
 public Map<String,Object> version(UUID id,int version,long user,AiResourceGuard.Action action){var doc=document(id,user,action);if(publicOnly((UUID)doc.get("base_id"),user,action)&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM ai_review_document d JOIN ai_resource_review r ON r.id=d.review_id WHERE d.document_id=? AND d.version=? AND r.state='APPROVED')",Boolean.class,id,version)))throw new WorkspaceDenied(404,"DocumentVersionNotPublished");var rows=jdbc.queryForList("SELECT * FROM ai_knowledge_document_version WHERE document_id=? AND version=?",id,version);if(rows.size()!=1)throw new WorkspaceDenied(404,"DocumentVersionNotFound");if(action==AiResourceGuard.Action.VIEW&&!"READY".equals(rows.getFirst().get("status")))try{base((UUID)doc.get("base_id"),user,AiResourceGuard.Action.EDIT);}catch(WorkspaceDenied e){throw new WorkspaceDenied(404,"DocumentVersionNotFound");}return rows.getFirst();}
 public Map<String,Object> file(UUID id,long user){var f=files.row(id);switch(f.get("purpose").toString()){case "CHAT","PERSONAL"->{if(!f.get("owner_user_id").toString().equals(Long.toString(user)))throw new WorkspaceDenied(404,"FileNotFound");}case "KNOWLEDGE"->{var rows=jdbc.queryForList("SELECT document_id,version FROM ai_knowledge_document_version WHERE file_id=?",id);if(rows.size()!=1)throw new WorkspaceDenied(404,"FileNotFound");version((UUID)rows.getFirst().get("document_id"),((Number)rows.getFirst().get("version")).intValue(),user,AiResourceGuard.Action.VIEW);}default->throw new WorkspaceDenied(404,"FileNotFound");}return f;}
 public List<Map<String,Object>> resolve(Object input,long user){if(input==null)return List.of();if(!(input instanceof List<?> ids)||ids.size()>8||new HashSet<>(ids).size()!=ids.size())throw new WorkspaceDenied(400,"InvalidKnowledgeDependencies");List<Map<String,Object>> result=new ArrayList<>();int count=0;for(Object value:ids){UUID id;try{id=UUID.fromString(value.toString());}catch(Exception e){throw new WorkspaceDenied(400,"InvalidKnowledgeDependencies");}var r=base(id,user,AiResourceGuard.Action.USE);var docs=jdbc.queryForList("SELECT d.id::text,v.version,d.auth_version,v.file_id::text FROM ai_knowledge_document d JOIN ai_knowledge_document_version v ON v.document_id=d.id AND v.version=CASE WHEN ? THEN (SELECT version FROM ai_public_document p WHERE p.resource_id=d.base_id AND p.document_id=d.id) ELSE d.indexed_version END WHERE d.base_id=? AND d.deleted_at IS NULL ORDER BY d.created_at LIMIT 101",publicOnly(id,user,AiResourceGuard.Action.USE),id);count+=docs.size();if(count>100)throw new WorkspaceDenied(400,"KnowledgeDocumentLimit");if(docs.isEmpty())throw new WorkspaceDenied(409,"KnowledgeIndexNotReady");result.add(Map.of("id",id.toString(),"version",r.get("published_version"),"authVersion",r.get("auth_version"),"documents",docs));}return result;}
 public List<Map<String,Object>> attachments(UUID session,long user){return jdbc.queryForList("SELECT id::text,filename,auth_version FROM ai_file WHERE session_id=? AND owner_user_id=? AND purpose='CHAT' AND deleted_at IS NULL ORDER BY created_at",session,user);}
 public void checkRun(UUID run,long user){for(var p:jdbc.queryForList("SELECT p.document_id,p.auth_version,d.auth_version AS current_auth,d.deleted_at,d.base_id FROM ai_run_document p JOIN ai_knowledge_document d ON d.id=p.document_id WHERE p.run_id=?",run)){base((UUID)p.get("base_id"),user,AiResourceGuard.Action.USE);if(p.get("deleted_at")!=null||!p.get("auth_version").equals(p.get("current_auth")))throw new WorkspaceDenied(403,"KnowledgeDocumentRevoked");}for(var p:jdbc.queryForList("SELECT p.auth_version,f.auth_version AS current_auth,f.deleted_at,f.owner_user_id FROM ai_run_file p JOIN ai_file f ON f.id=p.file_id WHERE p.run_id=?",run))if(p.get("deleted_at")!=null||!p.get("auth_version").equals(p.get("current_auth"))||!p.get("owner_user_id").toString().equals(Long.toString(user)))throw new WorkspaceDenied(403,"AttachmentRevoked");}
 public void checkHistory(UUID session,long user){for(UUID run:jdbc.queryForList("SELECT id FROM ai_run WHERE session_id=?",UUID.class,session))checkRun(run,user);}
}
